import asyncio,json,threading,http.server,functools
from pathlib import Path
from playwright.async_api import async_playwright
class Quiet(http.server.SimpleHTTPRequestHandler):
 def log_message(self,*a):pass
async def main():
 root=Path(__file__).resolve().parents[2];server=http.server.ThreadingHTTPServer(('127.0.0.1',8766),functools.partial(Quiet,directory=str(root)));threading.Thread(target=server.serve_forever,daemon=True).start()
 async with async_playwright()as p:
  b=await p.chromium.launch(executable_path='/tmp/chromium',args=['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']);page=await b.new_page(viewport={'width':960,'height':600});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));await page.goto('http://127.0.0.1:8766/dev.html',wait_until='domcontentloaded',timeout=120000);await page.wait_for_timeout(2500);await page.evaluate("document.getElementById('go').onclick()");await page.wait_for_timeout(5000);print('FLUIDS',await page.evaluate("({available:!!window.StrataFluids,metrics:window.StrataFluids?.metrics,buttons:[...document.querySelectorAll('button')].filter(b=>b.textContent==='Fluids').length})"));print('ERRORS',errors,flush=True);await page.evaluate("document.querySelectorAll('#news,#tutFx,#tour,#firstDrive').forEach(e=>e.hidden=true);if(window.StrataFluids){StrataFluids.scene(1);StrataFluids.set_rain(.5)}");await page.wait_for_timeout(3000);await page.evaluate("if(window.StrataFluids){const s=StrataFluids.system,p=s.focus;for(let x=-3;x<=3;x++)for(let z=-3;z<=3;z++)StrataFluids.spawn_spill('oil',[p[0]+x,p[1],p[2]+z],.002)}");await page.wait_for_timeout(1000);await page.evaluate("document.querySelectorAll('button').forEach(b=>{if(b.textContent==='Fluids')b.click()})");await page.screenshot(path=str(root/'fluids/tests/game_boot.png'));result=await page.evaluate("({available:!!window.StrataFluids,metrics:window.StrataFluids?.metrics,ledger:window.StrataFluids?.system.ledger(),gpuFloat:!!window.StrataFluids?.system.flip,vehicle:window.StrataFluids?.get_vehicle_state('player')})");result['errors']=errors;(root/'fluids/tests/game_results.json').write_text(json.dumps(result,indent=2));await b.close()
asyncio.run(main())
